# Training-frozen native expressed-gene components; no clinical/LR selection.
args<-commandArgs(trailingOnly=TRUE);input<-args[1];projection<-args[2];out<-args[3];runtime<-args[4];units_path<-args[5]
stopifnot(!dir.exists(out));dir.create(out,recursive=TRUE,mode='0700');.libPaths(c(file.path(runtime,c('library_v7','library_v5','library_v2','library')),.libPaths()));suppressPackageStartupMessages(library(Matrix))
units<-read.delim(gzfile(units_path),check.names=FALSE);tot<-aggregate(n_cells~sample_uid+major,data=units,FUN=sum);keys<-paste(tot$sample_uid,tot$major,sep='||');scope<-read.delim(file.path(projection,'public_slot_scope.tsv'),check.names=FALSE);saved<-read.delim(file.path(projection,'private_block_mean_scores.tsv'),check.names=FALSE);types<-unique(scope[,c('context','type')]);summary<-list();checks<-list()
read_part<-function(root,type,part){p<-file.path(root,paste0(type,'_',part));if(!file.exists(paste0(p,'_metadata.tsv')))return(NULL);md<-read.delim(paste0(p,'_metadata.tsv'),check.names=FALSE);g<-readLines(paste0(p,'_genes.tsv'));m<-readMM(gzfile(paste0(p,'_tpm.mtx.gz')));stopifnot(nrow(m)==length(g),ncol(m)==nrow(md),!anyDuplicated(g),!anyDuplicated(md$cell));rownames(m)<-g;colnames(m)<-md$cell;u<-units[match(md$unit_index,units$unit_index),];stopifnot(!anyNA(u$unit_index),identical(as.character(u$sample_uid),as.character(md$sample_uid)));md$fraction<-u$n_cells/tot$n_cells[match(paste(u$sample_uid,u$major,sep='||'),keys)];md$logN<-log1p(u$n_cells);list(md=md,m=m)}
for(i in seq_len(nrow(types))){
 q<-types[i,];key<-paste(q$context,q$type,sep='_');root<-file.path(input,sprintf('context_%04d',q$context));tr<-read_part(root,q$type,'discovery');te<-read_part(root,q$type,'holdout');D<-model.matrix(~cellQ+geneQ+fraction+logN,data=tr$md);qrD<-qr(D)
 if(qrD$rank!=ncol(D)){summary[[key]]<-data.frame(context=q$context,type=q$type,status='FULL_FOUR_COVARIATE_DESIGN_NOT_IDENTIFIABLE',expressed_genes=nrow(tr$m),nonconstant_genes=0,discovery_cells=nrow(tr$md),holdout_cells=if(is.null(te))0 else nrow(te$md),blocks=0);next}
 dense<-as.matrix(tr$m);mu<-rowMeans(dense);sigma<-apply(dense,1,sd);keep<-is.finite(sigma)&sigma>0;genes<-rownames(dense)[keep];Z<-t(sweep(sweep(dense[keep,,drop=FALSE],1,mu[keep],'-'),1,sigma[keep],'/'));coef<-qr.coef(qrD,Z);train_resid<-Z-D%*%coef;allB<-list();allmd<-list()
 for(part in c('discovery','holdout')){
  v<-if(part=='discovery')tr else te;if(is.null(v))next;stopifnot(identical(rownames(tr$m),rownames(v$m)))
  if(part=='discovery')C<-train_resid else {Zt<-t(sweep(sweep(as.matrix(v$m[genes,,drop=FALSE]),1,mu[keep],'-'),1,sigma[keep],'/'));Dt<-model.matrix(~cellQ+geneQ+fraction+logN,data=v$md);stopifnot(identical(colnames(D),colnames(Dt)));C<-Zt-Dt%*%coef}
  blocks<-sort(unique(v$md$sample));B<-do.call(rbind,lapply(blocks,function(b)colMeans(C[v$md$sample==b,,drop=FALSE])));rownames(B)<-blocks;colnames(B)<-genes;stopifnot(all(is.finite(B)));allB[[part]]<-B;allmd[[part]]<-data.frame(sample=blocks,partition=part)
 }
 B<-do.call(rbind,allB);md<-do.call(rbind,allmd);stopifnot(nrow(B)==nrow(md),!anyDuplicated(md$sample));rownames(B)<-md$sample;ss<-scope[scope$context==q$context&scope$type==q$type&scope$status=='FROZEN_RECONSTRUCTION_PASS',]
 for(j in seq_len(nrow(ss))){
  program<-ss$program[j];w<-readRDS(file.path(projection,paste(q$context,q$type,paste0(program,'_weights.rds'),sep='_')));ix<-match(w$genes,genes);stopifnot(!anyNA(ix),max(abs(mu[keep][ix]-w$gene_mean))<1e-10,max(abs(sigma[keep][ix]-w$gene_sd))<1e-10);pred<-as.numeric(B[,ix,drop=FALSE]%*%w$weight);sb<-saved[saved$context==q$context&saved$type==q$type&saved$program==program,];ki<-match(md$sample,sb$sample);stopifnot(!anyNA(ki),nrow(sb)==nrow(md));err<-max(abs(pred-sb$score[ki]));stopifnot(is.finite(err),err<1e-6);checks[[paste(key,program)]]<-data.frame(context=q$context,type=q$type,program=program,genes=length(w$genes),blocks=nrow(B),max_existing_score_error=err)
 }
 od<-file.path(out,key);dir.create(od,mode='0700');con<-gzfile(file.path(od,'private_genewise_block_components.tsv.gz'),'wt');write.table(t(B),con,sep='\t',row.names=TRUE,col.names=NA,quote=TRUE);close(con);write.table(md,file.path(od,'private_block_partitions.tsv'),sep='\t',row.names=FALSE,quote=TRUE);saveRDS(list(genes=genes,mean=mu[keep],sd=sigma[keep],quality_coefficients=coef,quality_columns=colnames(D)),file.path(od,'private_frozen_gene_transform.rds'));summary[[key]]<-data.frame(context=q$context,type=q$type,status='FROZEN_ALLGENE_BLOCK_COMPONENTS_PASS',expressed_genes=nrow(tr$m),nonconstant_genes=length(genes),discovery_cells=nrow(tr$md),holdout_cells=if(is.null(te))0 else nrow(te$md),blocks=nrow(B));write.table(do.call(rbind,summary),file.path(out,'public_all28_type_scope.tsv'),sep='\t',row.names=FALSE,quote=FALSE);rm(dense,Z,train_resid,B,allB);gc()
}
write.table(do.call(rbind,summary),file.path(out,'public_all28_type_scope.tsv'),sep='\t',row.names=FALSE,quote=FALSE);stopifnot(length(checks)==53);write.table(do.call(rbind,checks),file.path(out,'public_all53_existing_MCP_checks.tsv'),sep='\t',row.names=FALSE,quote=FALSE);writeLines('ALL28_TYPES_ACCOUNTED_ALL53_MCP_RECONSTRUCTIONS_PASS_NOT_TF_ACTIVITY_VALIDATION',file.path(out,'execution_complete.txt'))
